var DASH_LOG_SHEET = '\u30ED\u30B0';
var DASH_STALE_MINUTES = 15;

function dashMainValues_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheets()[0];
  var last = sh.getLastRow();
  if (last < 2) return [];
  return sh.getRange(2, 1, last - 1, 13).getDisplayValues();
}

function dashLogValues_() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName(DASH_LOG_SHEET);
  if (!sh || sh.getLastRow() < 2) return [];
  return sh.getRange(2, 1, sh.getLastRow() - 1, 5).getDisplayValues();
}

function dashParseDate_(value) {
  if (value instanceof Date) return value;
  var s = String(value || '').trim();
  if (!s) return null;
  var m = s.match(/(\\d{4})\\D(\\d{1,2})\\D(\\d{1,2})\\D*\\s*(\\d{1,2}):(\\d{2})/);
  if (!m) return null;
  return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
}

function dashClassify_(row) {
  var onOff = String(row[6] || '').toUpperCase();
  if (onOff === 'OFF') return 'off';
  var lastCheck = dashParseDate_(row[4]);
  if (!lastCheck) return 'error';
  if (new Date().getTime() - lastCheck.getTime() > DASH_STALE_MINUTES * 60000) return 'stale';
  var operation = String(row[1] || row[2] || '');
  if (!operation || operation.indexOf('\u904B\u884C\u306A\u3057') !== -1) return 'idle';
  return 'running';
}

function getVehicleStatusList() {
  return dashMainValues_().map(function (row, i) {
    return {
      row: i + 2,
      name: row[3],
      operation: row[1] || row[2],
      lastCheck: row[4],
      lastRun: row[5],
      onOff: row[6],
      stop: row[9],
      via: row[10],
      nextTime: row[11],
      nextOperation: row[12],
      state: dashClassify_(row)
    };
  }).filter(function (v) { return v.name || v.operation; });
}

function getDashboardData() {
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheets()[0];
  var vehicles = getVehicleStatusList();
  var logs = getVehicleCalendarData('', '');
  return {
    updatedAt: sheet.getRange(1, 8).getDisplayValue(),
    fetchedAt: new Date().toISOString(),
    vehicles: vehicles,
    logCount: logs.count || 0
  };
}

function getVehicleCalendarData(vehicleName, month) {
  var rows = dashLogValues_();
  var daily = {};
  SpreadsheetApp.getActiveSpreadsheet().getSheets().forEach(function (sh) {
    var m = String(sh.getName()).match(/^(\\d{1,2})\u6708(\\d{1,2})\u65E5\u904B\u7528\u8868$/);
    if (m) daily[m[1] + '-' + ('0' + m[2]).slice(-2)] = sh.getName();
  });

  var days = {};
  var count = 0;
  rows.forEach(function (row) {
    if (vehicleName && row[1] !== vehicleName) return;
    var d = dashParseDate_(row[0]);
    if (!d) return;
    var key = Utilities.formatDate(d, 'Asia/Tokyo', 'yyyy-MM-dd');
    if (month && key.substring(0, 7) !== month) return;
    count++;
    if (!days[key]) days[key] = { date: key, logs: [], dailySheet: daily[key] || '' };
    days[key].logs.push({ at: row[0], kind: row[2], from: row[3], to: row[4] });
  });

  return { vehicle: vehicleName, month: month, days: days, count: count };
}

function searchOperationLogs(criteria) {
  var c = criteria || {};
  var rows = dashLogValues_();
  var result = [];
  rows.forEach(function (row) {
    var d = dashParseDate_(row[0]);
    if (!d) return;
    var key = Utilities.formatDate(d, 'Asia/Tokyo', 'yyyy-MM-dd');
    if (c.from && key < c.from) return;
    if (c.to && key > c.to) return;
    if (c.vehicle && String(row[1]).indexOf(c.vehicle) === -1) return;
    if (c.kind && String(row[2]).indexOf(c.kind) === -1) return;
    if (c.before && String(row[3]).indexOf(c.before) === -1) return;
    if (c.after && String(row[4]).indexOf(c.after) === -1) return;
    result.push({ at: row[0], date: key, vehicle: row[1], kind: row[2], from: row[3], to: row[4] });
  });
  return { count: result.length, logs: result };
}

function getTimeSlotAnalysis(fromDate, toDate) {
  var found = searchOperationLogs({ from: fromDate, to: toDate });
  var hours = [];
  var weeks = [];
  var months = [];
  var i;
  for (i = 0; i < 24; i++) hours.push({ hour: i, total: 0, start: 0, change: 0 });
  for (i = 0; i < 7; i++) weeks.push({ index: i, total: 0 });
  var monthMap = {};

  found.logs.forEach(function (log) {
    var d = dashParseDate_(log.at);
    if (!d) return;
    var h = Number(Utilities.formatDate(d, 'Asia/Tokyo', 'H'));
    var kind = String(log.kind || '');
    hours[h].total++;
    if (kind.indexOf('\u904B\u884C\u958B\u59CB') !== -1) hours[h].start++;
    else if (kind.indexOf('\u904B\u884C\u7D42\u4E86') === -1) hours[h].change++;
    weeks[(d.getDay() + 6) % 7].total++;
    var mk = log.date.substring(0, 7);
    if (!monthMap[mk]) monthMap[mk] = { label: mk, total: 0, start: 0 };
    monthMap[mk].total++;
    if (kind.indexOf('\u904B\u884C\u958B\u59CB') !== -1) monthMap[mk].start++;
  });

  Object.keys(monthMap).forEach(function (k) { months.push(monthMap[k]); });
  months.sort(function (a, b) { return a.label < b.label ? -1 : 1; });
  return { count: found.count, hours: hours, weekdays: weeks, months: months };
}

function getFavoriteVehicleData(vehicleNames) {
  var names = vehicleNames || [];
  return getVehicleStatusList().filter(function (v) { return names.indexOf(v.name) !== -1; });
}

function getVehicleComparisonData(vehicleNames) {
  var names = vehicleNames || [];
  var list = getFavoriteVehicleData(names);
  var counts = {};
  dashLogValues_().forEach(function (row) {
    if (names.indexOf(row[1]) === -1) return;
    counts[row[1]] = (counts[row[1]] || 0) + 1;
  });
  return list.map(function (v) {
    return {
      name: v.name,
      state: v.state,
      operation: v.operation,
      stop: v.stop,
      lastCheck: v.lastCheck,
      lastRun: v.lastRun,
      changeCount: counts[v.name] || 0
    };
  });
}
